'use strict';

const assert = require('node:assert/strict');
const path = require('node:path');
const root = process.argv[2] ?? '/qualification/named-source/services/api/prisma';
const generic = require(path.join(root,'task16-current259-seven-preimage.cjs'));
const {bindNamedSevenPreimage,bindNamedSevenDelta} = require(path.join(root,'task16-seven-preimage-named-owner.cjs'));
const guarded = "OR current_user <> 'jg_task01_owner' OR current_user <> session_user THEN";
const named = "OR current_user <> 'jiangkong' OR current_user <> session_user THEN";
const nonce = 'a'.repeat(64);
const baseline = generic.renderCurrent259SevenPreimage(nonce);
const result = bindNamedSevenPreimage(baseline);
assert.equal(result.setupSql,baseline.setupSql.replace(guarded,named));
assert.equal(result.witnessSql,baseline.witnessSql);
assert.equal(result.cleanupSql,baseline.cleanupSql);
assert.equal(generic.renderCurrent259SevenPreimage(nonce).setupSql,baseline.setupSql);
assert.throws(()=>bindNamedSevenPreimage({...baseline,setupSql:baseline.setupSql.replace(guarded,named)}),/NAMED_SEVEN_PREIMAGE_OWNER_PREDICATE/);
assert.throws(()=>bindNamedSevenPreimage({...baseline,setupSql:baseline.setupSql+guarded}),/NAMED_SEVEN_PREIMAGE_OWNER_PREDICATE/);
assert.equal(typeof require(path.join(root,'task16-current259-seven-install.cjs')).createNativeTask12ArchiveSevenMaterial,'function');
const historicalDelta = require(path.join(root,'task16-schema205-scope.cjs')).schema205SevenDeltaSql();
const oldOid = "p.proowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='jg_task01_owner')";
const newOid = "p.proowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='jiangkong' AND oid=10)";
const namedDelta = bindNamedSevenDelta(historicalDelta);
assert.equal(namedDelta,historicalDelta.replace(oldOid,newOid));
assert.ok(namedDelta.includes('pg_catalog.to_regprocedure'));
assert.ok(namedDelta.includes('p.prosrc'));
assert.throws(()=>bindNamedSevenDelta(namedDelta),/NAMED_SEVEN_DELTA_OWNER_PREDICATE/);
assert.throws(()=>bindNamedSevenDelta(historicalDelta+oldOid),/NAMED_SEVEN_DELTA_OWNER_PREDICATE/);
console.log('NAMED_290_SEVEN_PREIMAGE_AND_DELTA_OFFLINE_PASSED');
